// lib/ppt-assets.ts
//
// Embedded image assets for the uxproof presentation generator.
// All entries are full data:image/...;base64 URIs that pptxgenjs embeds
// directly into the .pptx (no external file dependencies).
//
// The template is strictly monochrome — the cover photo is stored
// pre-converted to grayscale so no colour enters the deck.

export const ASSETS = {
  // Grayscale cover photo — right half of the cover slide
  COVER_IMAGE: 'data:image/jpeg;base64,',
};

/**
 * Throws a descriptive error if any required image is missing.
 * Called from generatePowerPoint to fail fast.
 */
export function assertAssetsReady(): void {
  const missing: string[] = [];
  for (const [name, value] of Object.entries(ASSETS)) {
    if (!value || value.length < 100 || !value.startsWith('data:image/')) {
      missing.push(name);
    }
  }
  if (missing.length) {
    throw new Error(
      `[ppt-assets] missing/invalid image data for: ${missing.join(', ')}. ` +
      'Each ASSETS entry must be a full "data:image/...;base64,..." URI.',
    );
  }
}
